import React, { Component } from 'react'
import NewsItem from './NewsItem'
import Spinner from './Spinner';
import PropTypes from 'prop-types'
import InfiniteScroll from "react-infinite-scroll-component";


export class News extends Component {
  static defaultProps = {
  country:'us',
  pageSize:5,
  category:'general',
  }

  static propTypes = {
    country:PropTypes.string,
    pageSize:PropTypes.number,
    category:PropTypes.string,
  }
  capitalizeFirstLetter=(string) => {
    return string.charAt(0).toUpperCase() + string.slice(1);
}
    constructor(props) {
      super(props);
       console.log("hello ,i am a constructor from News component")
       this.state={
         articles:[],
         loading:false,
         page:1,
         totalResults:0

 
       }
       document.title=`${this.capitalizeFirstLetter(this.props.category)}- NewsMonkey`;
     }
     async updateNews(){
      const url=`https://newsapi.org/v2/top-headlines?country=${this.props.country}&category=${this.props.category}&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page= ${this.state.page}&pageSize=${this.props.pageSize}`;
        let data= await fetch(url);
        let parsedData=await data.json()
        console.log(parsedData);
        this.setState({articles:parsedData.articles,totalArticles:parsedData.totalResults, loading:false
          
        })

     } 
     async componentDidMount(){
        // console.log("cdm");
        // let url=`https://newsapi.org/v2/top-headlines?country=${this.props.country}&category=${this.props.category}&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page=1&pageSize=${this.props.pageSize}`;
        // let data= await fetch(url);
        // let parsedData=await data.json()
        // console.log(parsedData);
        // this.setState({articles:parsedData.articles,totalArticles:parsedData.totalResults,loading:false})
        this.updateNews();
      }

      handlePrevClick = async()=>{
        // console.log("prev");
        // let url=`https://newsapi.org/v2/top-headlines?country=${this.props.country}&category=${this.props.category}&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page=${this.state.page-1}&pageSize=${this.props.pageSize}`;
        // this.setState({loading:true});
        // let data= await fetch(url);
        // let parsedData=await data.json()
        // console.log(parsedData);
        // this.setState({
        //   page: this.state.page-1,
        //   articles:parsedData.articles       
        // })
        this.setState({page:this.state.page-1});
        this.updateNews();

      }
        handleNextClick =  async()=>{
        console.log("next");
        //if(!(this.state.page+1>Math.ceil(this.state.totalResults/10))){
    //   let url=`https://newsapi.org/v2/top-headlines?country=${this.props.country}&category=${this.props.category}&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page=${this.state.page+1}&pageSize=${this.props.pageSize}`;
        //   this.setState({loading:true});
        // let data= await fetch(url);
        // let parsedData=await data.json()
        // console.log(parsedData);
        // //zthis.setState({articles:parsedData.articles})

        // this.setState({
        //   page: this.state.page+1,
        //   articles:parsedData.articles,
        //   loading:false
        // })
        this.setState({page:this.state.page+1});
        this.updateNews();
        } 

        fetchMoreData = async () => {
          this.setState({page:this.state.page+1});
          const url=`https://newsapi.org/v2/top-headlines?country=${this.props.country}&category=${this.props.category}&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page= ${this.state.page}&pageSize=${this.props.pageSize}`;
          this.setState({loading:true});
          let data= await fetch(url);
          let parsedData=await data.json()
          console.log(parsedData);
          this.setState({articles:this.state.articles.concate(parsedData.articles),totalArticles:parsedData.totalResults, loading:false
            
          })
        };
      
    
  render(){
    return (
      <div className="container my-3">
        <h1 className="text-center" style={{margin:'35px 0px'}}>Newsmonkey -Top  {this.capitalizeFirstLetter(this.props.category)} Headlines</h1>
        {/* {this.state.loading && <Spinner/>} */}
        {/* <h2> Newsmonkey -Top Headlines</h2> */}
        <InfiniteScroll
          dataLength={this.state.articles.length}
          next={this.fetchMoreData}
          hasMore={ this.state.articles.length!==this.state.totalResults}
          loader={<Spinner/>}
        >
          .
        <div className="row">
        {/* {!this.state.loading && this.state.articles.map((element)=>{ */}
        {this.state.articles.map((element)=>{
             return <div className="col-md-4" key={element.url}>
               <NewsItem  title={element?element.title:""} description={element.description?element.description:""} imageurl={element.urlToImage} newsUrl={element.url} author={element.author } date={element.publishedAt}  source={element.source.name}/>
          </div>
          
          // <div className="col-md-4"> <NewsItem key={element.url} title={element.title} description={element.description} imageurl={element.urlToImage} newsUrl="TODO"/>
          // </div> 
        })}
        
        </div>
        </InfiniteScroll>
      {/* <div className="col-md-4">
        <NewsItem title="mytitle" description="mydesc" imageurl="https://encrypted-tbn1.gstatic.com/licensed-image?q=tbn:ANd9GcR6AK1OtJ2FXnHR6omrAJwzJUpDnlRN4K-L3NfsTyFLYE2M4MFb26tkd0lxmNiNcEtINJw_Bjvc3RrQysQ"/>
        </div>
        <div className="col-md-4">
        <NewsItem title="mytitle" description="mydesc" imageurl="https://encrypted-tbn1.gstatic.com/licensed-image?q=tbn:ANd9GcR6AK1OtJ2FXnHR6omrAJwzJUpDnlRN4K-L3NfsTyFLYE2M4MFb26tkd0lxmNiNcEtINJw_Bjvc3RrQysQ"/>
        </div> */}
        {/* <div className="col-md-4">
        <NewsItem title="mytitle" description="mydesc"/>
        </div> */}
        
        {/* <div className="container d-flex justify-content-between">
        <button  disabled={this.state.page<=1}type="button" className="btn btn-dark" onClick={this.handlePrevClick}> &larr; Previous</button>
        <button  disabled= {this.state.page+1>Math.ceil(this.state.totalResults/this.props.pageSize)}type="button" className="btn btn-dark" onClick={this.handleNextClick}> Next &rarr;</button>
        </div> */}
        </div>
       )
  }
}
export default News
